def tr_lower(s):
    """Türkçe kurallarına göre küçük harfe çevir."""
    result = []
    for ch in s:
        if ch == 'I':
            result.append('ı')
        elif ch == 'İ':
            result.append('i')
        else:
            result.append(ch.lower())
    return ''.join(result)


def tr_upper(s):
    """Türkçe kurallarına göre büyük harfe çevir."""
    result = []
    for ch in s:
        if ch == 'i':
            result.append('İ')
        elif ch == 'ı':
            result.append('I')
        else:
            result.append(ch.upper())
    return ''.join(result)


def tr_sorted(words):
    """Kelimeleri Türk alfabesine göre sıralanmış yeni liste olarak döndür."""
    turk_order = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    def sort_key(word):
        # Kelimenin Türkçe küçük harfe çevrilmiş hali
        lower_word = tr_lower(word)

        # Her karakter için sıralama önceliği hesapla
        key_parts = []
        for ch in lower_word:
            if ch in turk_order:
                # Türk alfabesindeki pozisyon
                pos = turk_order.index(ch)
                key_parts.append(pos)
            else:
                # Türk alfabesinde olmayan karakterler (boşluk, noktalama vb.)
                # Unicode kod noktasına göre sıralanır ama tüm Türk harflerinden önce gelir
                # Bu yüzden çok küçük bir değer atayalım
                key_parts.append(-1)

        # Kelimenin uzunluğu da önemli: önek ise kısa olan önce gelir
        return (tuple(key_parts), len(word))

    # Orijinal listeyi değiştirmeden yeni liste oluştur ve sırala
    # Eşitlik durumunda girdideki sıraları korumak için stable sort kullanıyoruz
    sorted_words = sorted(words, key=sort_key)

    return sorted_words

